-- FOUR GIRLS SKY - Delta/iOS auto-reapply
-- One-file version: all six sky images are embedded in this script.

local env = (getgenv and getgenv()) or _G
local KEY = "__FOUR_GIRLS_SKY_V1"

if env[KEY] and env[KEY].connections then
    for _, c in ipairs(env[KEY].connections) do
        pcall(function() c:Disconnect() end)
    end
end

local state = {connections = {}}
env[KEY] = state
local function keep(c) if c then table.insert(state.connections, c) end end

local wf = writefile
local ca = getcustomasset or getsynasset
if not wf or not ca then
    warn("[Four Girls Sky] writefile/getcustomasset unavailable")
    return
end

local B64 = {
    lf = [==[]==],
    dn = [==[]==],
    rt = [==[]==],
    bk = [==[]==],
    ft = [==[]==],
    up = [==[]==],
}

local function decode(s)
    if crypt and crypt.base64decode then return crypt.base64decode(s) end
    if crypt and crypt.base64 and crypt.base64.decode then return crypt.base64.decode(s) end
    if syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then
        return syn.crypt.base64.decode(s)
    end
    error("No base64 decoder available")
end

local assets = {}
for _, side in ipairs({"lf","dn","rt","bk","ft","up"}) do
    local ok, bytes = pcall(decode, B64[side])
    if not ok then
        warn("[Four Girls Sky] decode failed: "..side)
        return
    end
    local filename = "four_girls_sky_"..side..".jpg"
    writefile(filename, bytes)
    local ok2, asset = pcall(ca, filename)
    if not ok2 or type(asset) ~= "string" then
        warn("[Four Girls Sky] custom asset failed: "..side)
        return
    end
    assets[side] = asset
end

local Lighting = game:GetService("Lighting")
local SKY_NAME = "FourGirlsSky_Delta"

local applying = false
local function applySky()
    if applying or env[KEY] ~= state then return end
    applying = true

    local sky = Lighting:FindFirstChild(SKY_NAME)
    if not sky then
        sky = Instance.new("Sky")
        sky.Name = SKY_NAME
        sky.Parent = Lighting
    end

    pcall(function()
        sky.SkyboxLf = assets.lf
        sky.SkyboxDn = assets.dn
        sky.SkyboxRt = assets.rt
        sky.SkyboxBk = assets.bk
        sky.SkyboxFt = assets.ft
        sky.SkyboxUp = assets.up
        sky.StarCount = 0
        sky.CelestialBodiesShown = false
    end)

    -- Disable competing Sky objects without deleting them.
    for _, obj in ipairs(Lighting:GetChildren()) do
        if obj:IsA("Sky") and obj ~= sky then
            pcall(function() obj.Parent = nil end)
        end
    end

    applying = false
end

applySky()

keep(Lighting.ChildAdded:Connect(function(obj)
    if env[KEY] ~= state then return end
    if obj:IsA("Sky") and obj.Name ~= SKY_NAME then
        task.defer(applySky)
    end
end))

keep(Lighting.ChildRemoved:Connect(function(obj)
    if env[KEY] ~= state then return end
    if obj.Name == SKY_NAME then
        task.defer(applySky)
    end
end))

for _, t in ipairs({1, 3, 7, 15}) do
    task.delay(t, applySky)
end

print("[Four Girls Sky] loaded.")
